-- Reference billing shape, isolated test schema only.
CREATE TABLE api_cloud_billing_periods(period_id text PRIMARY KEY,account_id text NOT NULL,billing_provider text NOT NULL DEFAULT 'stripe',provider_subscription_id text,status text NOT NULL,currency text NOT NULL DEFAULT 'USD',period_start bigint NOT NULL,period_end bigint NOT NULL,base_price_micros bigint NOT NULL,included_provider_cost_micros bigint NOT NULL,markup_basis_points bigint NOT NULL,overage_cap_micros bigint NOT NULL,updated_at bigint NOT NULL);
CREATE TABLE api_cloud_billing_ledger(entry_id text PRIMARY KEY,period_id text NOT NULL,kind text NOT NULL,amount_micros bigint NOT NULL);
CREATE TABLE api_cloud_billing_usage(entry_id text PRIMARY KEY,period_id text NOT NULL,resource_kind text NOT NULL,resource_id text NOT NULL,provider text NOT NULL,provider_execution_id text,started_at bigint NOT NULL,ended_at bigint NOT NULL,vcpu_count bigint NOT NULL,memory_mib bigint NOT NULL,provider_cost_micros bigint NOT NULL,status text NOT NULL,created_at bigint NOT NULL);
CREATE TABLE api_cloud_billing_reservations(period_id text NOT NULL,resource_kind text NOT NULL,resource_id text NOT NULL,provider text NOT NULL,started_at bigint NOT NULL,updated_at bigint NOT NULL,vcpu_count bigint NOT NULL,memory_mib bigint NOT NULL,provider_cost_micros bigint NOT NULL,expires_at bigint NOT NULL);
CREATE TABLE api_cloud_billing_meter_reconciliations(period_id text NOT NULL,provider text NOT NULL,created_at bigint NOT NULL);
CREATE TABLE api_cloud_billing_cap_commands(period_id text NOT NULL,idempotency_key text NOT NULL,overage_cap_micros bigint NOT NULL,created_at bigint NOT NULL,PRIMARY KEY(period_id,idempotency_key));
